"""Procedural ink line work for the spellbook pages (drawn here, not generated by a model).

Writes to Assets/Spellbook/UI:
  UI_MedalUnderStorm / FrostBreath / IceComet / AbsoluteZero  - 512x512 underlays inside the medallion
      windows (same canvas as UI_FrameRing / UI_CircleMask; the scene masks them by UI_CircleMask).
      Drawn around each thumbnail's own empty areas, so the spell art stays the main object.
  UI_RightPageInk  - a full right-sheet layer (page px x PX): a large thin-line ice diagram behind the
      animation area, dotted connectors and small ink studies in the margins. Nothing below the title.

Style: dark brown ink on transparent (the parchment shows through), a hand-drawn wobble, line weights
1-3 px, very sparse muted cold accents. No fills.
"""
import math
import random
from pathlib import Path

import numpy as np
from PIL import Image, ImageDraw, ImageFilter

ROOT = Path(__file__).resolve().parents[1]
UI = ROOT / "Assets" / "Spellbook" / "UI"

INK = (58, 34, 17)
COLD = (62, 96, 122)
SS = 3                     # supersampling

# Medallion canvas: UI_FrameRing 512 px, window radius 173 px (UI_CircleMask r 176)
MED = 512
MED_R = 176

# Right sheet in page px (SpellbookSceneBuilder / PageSurfaces.json): 1187 x 1545.7, origin at the centre
PAGE_W, PAGE_H = 1187.0, 1545.7
PX = 1.3                   # texture px per page px (1543 x 2010, under the 2048 import limit)
ART_REGION = (-390.5, -175.7, 391.9, 717.7)   # Ice Storm's visible area = the animation region


class Ink:
    """Two coverage layers (ink, cold accent) drawn at SS x, composited to straight RGBA."""

    def __init__(self, w, h, seed):
        self.w, self.h = w, h
        self.ink = Image.new("L", (w * SS, h * SS), 0)
        self.cold = Image.new("L", (w * SS, h * SS), 0)
        self.rng = random.Random(seed)

    def _layer(self, cold):
        return ImageDraw.Draw(self.cold if cold else self.ink)

    def wobble(self, pts, amp=0.6):
        # плавное дрожание руки: сумма двух синусов вдоль линии
        out = []
        ph1, ph2 = self.rng.uniform(0, 6.28), self.rng.uniform(0, 6.28)
        n = len(pts)
        for i, (x, y) in enumerate(pts):
            t = i / max(1, n - 1)
            d = amp * (math.sin(ph1 + t * 9.0) + 0.5 * math.sin(ph2 + t * 23.0))
            if 0 < i < n - 1:
                dx, dy = pts[i + 1][0] - pts[i - 1][0], pts[i + 1][1] - pts[i - 1][1]
                L = math.hypot(dx, dy) or 1.0
                x, y = x - dy / L * d, y + dx / L * d
            out.append((x, y))
        return out

    def line(self, pts, w=1.6, a=0.85, cold=False, wob=0.6):
        pts = self.wobble(pts, wob) if wob else pts
        p = [(x * SS, y * SS) for x, y in pts]
        self._layer(cold).line(p, fill=int(255 * a), width=max(1, int(round(w * SS))), joint="curve")

    def dashed(self, pts, dash=10.0, gap=7.0, **kw):
        seg, acc, on = [pts[0]], 0.0, True
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            L = math.hypot(x1 - x0, y1 - y0)
            acc += L
            seg.append((x1, y1))
            if acc >= (dash if on else gap):
                if on and len(seg) > 1:
                    self.line(seg, **kw)
                seg, acc, on = [(x1, y1)], 0.0, not on
        if on and len(seg) > 1:
            self.line(seg, **kw)

    def circle(self, cx, cy, r, w=1.6, a=0.85, a0=0.0, a1=360.0, cold=False, steps=None, dashed=False, wob=0.5):
        steps = steps or max(24, int(abs(a1 - a0) / 360 * r * 0.8))
        pts = [(cx + r * math.cos(math.radians(a0 + (a1 - a0) * i / steps)),
                cy + r * math.sin(math.radians(a0 + (a1 - a0) * i / steps))) for i in range(steps + 1)]
        (self.dashed if dashed else self.line)(pts, w=w, a=a, cold=cold, wob=wob)

    def dot(self, x, y, r, a=0.8, cold=False):
        r *= SS
        self._layer(cold).ellipse([x * SS - r, y * SS - r, x * SS + r, y * SS + r], fill=int(255 * a))

    def star4(self, x, y, s, a=0.85, w=1.2):
        self.line([(x - s, y), (x + s, y)], w=w, a=a, wob=0)
        self.line([(x, y - s), (x, y + s)], w=w, a=a, wob=0)
        self.line([(x - s * 0.45, y - s * 0.45), (x + s * 0.45, y + s * 0.45)], w=w * 0.7, a=a * 0.8, wob=0)
        self.line([(x - s * 0.45, y + s * 0.45), (x + s * 0.45, y - s * 0.45)], w=w * 0.7, a=a * 0.8, wob=0)

    def snowflake(self, x, y, s, a=0.85, w=1.3, rot=0.0, cold=False):
        for k in range(6):
            t = math.radians(rot + k * 60)
            ex, ey = x + s * math.cos(t), y + s * math.sin(t)
            self.line([(x, y), (ex, ey)], w=w, a=a, cold=cold, wob=0)
            for f in (0.45, 0.72):
                bx, by = x + s * f * math.cos(t), y + s * f * math.sin(t)
                for side in (-1, 1):
                    tb = t + side * math.radians(42)
                    L = s * (0.32 if f < 0.6 else 0.22)
                    self.line([(bx, by), (bx + L * math.cos(tb), by + L * math.sin(tb))], w=w * 0.8, a=a, cold=cold, wob=0)

    def crystal(self, x, y, s, rot=0.0, a=0.85, w=1.3):
        # гранёный кристалл: вытянутый шестиугольник с осью и гранями
        t = math.radians(rot)
        c, si = math.cos(t), math.sin(t)
        local = [(0, -s), (0.32 * s, -0.55 * s), (0.32 * s, 0.6 * s), (0, s * 0.85), (-0.32 * s, 0.6 * s), (-0.32 * s, -0.55 * s), (0, -s)]
        P = [(x + px * c - py * si, y + px * si + py * c) for px, py in local]
        self.line(P, w=w, a=a, wob=0.3)
        for i in (1, 2, 4, 5):
            self.line([P[0] if i in (1, 5) else P[3], ((P[i][0] + x) / 2, (P[i][1] + y) / 2)], w=w * 0.6, a=a * 0.7, wob=0.2)
        self.line([P[0], P[3]], w=w * 0.6, a=a * 0.6, wob=0.2)

    def fern(self, x, y, ang, length, depth=3, a=0.75, w=1.2, cold=False):
        # морозный узор: ветвление с убывающей длиной
        if depth == 0 or length < 4:
            return
        steps = 6
        pts = [(x, y)]
        cx, cy, t = x, y, math.radians(ang)
        for i in range(steps):
            t += math.radians(self.rng.uniform(-6, 6))
            cx += length / steps * math.cos(t)
            cy += length / steps * math.sin(t)
            pts.append((cx, cy))
        self.line(pts, w=w, a=a, cold=cold, wob=0)
        for i in range(1, steps):
            bx, by = pts[i]
            for side in (-1, 1):
                if self.rng.random() < 0.85:
                    self.fern(bx, by, math.degrees(t) + side * self.rng.uniform(45, 65),
                              length * (0.42 - 0.04 * i), depth - 1, a * 0.9, w * 0.8, cold)

    def crack(self, x, y, ang, length, depth=3, a=0.8, w=1.5):
        pts = [(x, y)]
        cx, cy, t = x, y, math.radians(ang)
        n = max(3, int(length / 9))
        for i in range(n):
            t += math.radians(self.rng.uniform(-28, 28))
            seg = length / n
            cx += seg * math.cos(t)
            cy += seg * math.sin(t)
            pts.append((cx, cy))
            if depth > 0 and self.rng.random() < 0.28:
                self.crack(cx, cy, math.degrees(t) + self.rng.choice((-1, 1)) * self.rng.uniform(30, 70),
                           length * self.rng.uniform(0.3, 0.55), depth - 1, a * 0.85, w * 0.7)
        self.line(pts, w=w, a=a, wob=0)

    def image(self, clip=None):
        ink = np.asarray(self.ink.resize((self.w, self.h), Image.LANCZOS)).astype(np.float32) / 255
        cold = np.asarray(self.cold.resize((self.w, self.h), Image.LANCZOS)).astype(np.float32) / 255
        if clip is not None:
            ink, cold = ink * clip, cold * clip
        a = 1 - (1 - ink) * (1 - cold)
        rgb = (np.array(COLD) * cold[..., None] * (1 - ink[..., None]) + np.array(INK) * ink[..., None]) / np.maximum(a, 1e-4)[..., None]
        out = np.dstack([np.clip(rgb, 0, 255), np.clip(a * 255, 0, 255)]).astype(np.uint8)
        return Image.fromarray(out, "RGBA")


def free_mask(thumb, dilate=9):
    """Where the thumbnail is transparent (room for the underlay), shrunk away from the art."""
    al = thumb.split()[3].filter(ImageFilter.MaxFilter(dilate))
    return np.asarray(al).astype(np.float32) < 24


def free_spots(free, rng, n, r_min, inner=165, spacing=60, tries=4000):
    pts = []
    c = MED / 2
    for _ in range(tries):
        if len(pts) >= n:
            break
        x, y = rng.uniform(c - inner, c + inner), rng.uniform(c - inner, c + inner)
        if math.hypot(x - c, y - c) > inner - r_min or not free[int(y), int(x)]:
            continue
        if any(math.hypot(x - px, y - py) < spacing for px, py in pts):
            continue
        # всё пятно свободно
        ok = all(free[int(y + r_min * math.sin(t)), int(x + r_min * math.cos(t))] for t in np.linspace(0, 6.28, 12))
        if ok:
            pts.append((x, y))
    return pts


def disc_clip(size, r, soft=3.0):
    Y, X = np.mgrid[0:size, 0:size].astype(np.float32)
    d = np.hypot(X - size / 2 + 0.5, Y - size / 2 + 0.5)
    return np.clip((r - d) / soft, 0, 1)


MED_W = 1.9      # медальон ~290 px на экране: штрих толще, чем на листе


def common_ring(d):
    # общий для всех четырёх подложек тонкий внутренний бордюр окна
    c = MED / 2
    d.circle(c, c, 167, w=1.6 * MED_W, a=0.7, wob=0.3)
    d.circle(c, c, 157, w=0.9 * MED_W, a=0.55, dashed=True, wob=0.2)


def medal_storm(thumb):
    d = Ink(MED, MED, 11)
    common_ring(d)
    c = MED / 2
    free = free_mask(thumb)
    # тонкие спиральные линии ветра вокруг центра, разорванные
    for k in range(7):
        rot = k * 51.4
        pts = []
        for i in range(90):
            th = math.radians(rot + i * 4.2)
            r = 48 + i * 1.45
            pts.append((c + r * math.cos(th), c + 8 + r * 0.62 * math.sin(th)))
        start = d.rng.randint(0, 30)
        d.line(pts[start:start + d.rng.randint(35, 60)], w=1.3 * MED_W, a=0.75, wob=0.8)
    # ветер у края: длинные дуги вдоль окна на свободных сторонах
    for k in range(10):
        r = d.rng.uniform(118, 150)
        a0 = d.rng.uniform(0, 360)
        d.circle(c, c + 6, r, w=1.1 * MED_W, a=0.62, a0=a0, a1=a0 + d.rng.uniform(25, 55), wob=1.2)
    # снежная пыль
    for _ in range(260):
        x, y = d.rng.uniform(c - 170, c + 170), d.rng.uniform(c - 170, c + 170)
        if free[int(y), int(x)] and math.hypot(x - c, y - c) < 160:
            d.dot(x, y, d.rng.uniform(1.0, 2.4), a=d.rng.uniform(0.45, 0.85), cold=d.rng.random() < 0.25)
    # небольшие ледяные зарисовки в свободных местах
    for i, (x, y) in enumerate(free_spots(free, d.rng, 5, 22, spacing=70, inner=150)):
        if i % 2 == 0:
            d.crystal(x, y, 22, rot=d.rng.uniform(-30, 30), a=0.85, w=1.3 * MED_W)
        else:
            d.snowflake(x, y, 15, a=0.8, w=1.2 * MED_W, rot=d.rng.uniform(0, 60))
    return d.image(disc_clip(MED, MED_R))


def medal_frost_breath(thumb):
    d = Ink(MED, MED, 23)
    common_ring(d)
    c = MED / 2
    free = free_mask(thumb)
    mouth = (240, 190)          # пасть дракона на миниатюре (кадр 10)
    # линии потока из пасти: веер плавных кривых вправо-вниз
    for k in range(9):
        ang = math.radians(-28 + k * 11)
        L = 210
        ctrl = (mouth[0] + 90 * math.cos(ang - 0.25), mouth[1] + 90 * math.sin(ang - 0.25))
        end = (mouth[0] + L * math.cos(ang), mouth[1] + L * math.sin(ang))
        pts = [((1 - t) ** 2 * mouth[0] + 2 * (1 - t) * t * ctrl[0] + t * t * end[0],
                (1 - t) ** 2 * mouth[1] + 2 * (1 - t) * t * ctrl[1] + t * t * end[1]) for t in np.linspace(0.12, 1, 40)]
        d.dashed(pts, dash=d.rng.uniform(14, 26), gap=d.rng.uniform(5, 9), w=1.2 * MED_W, a=0.72)
    # морозный орнамент от края внизу слева и сверху справа
    for ang, (x, y) in ((-60, (150, 405)), (-25, (108, 335)), (-95, (222, 428)), (-120, (300, 425)), (150, (395, 120))):
        d.fern(x, y, ang, 82, depth=3, a=0.72, w=1.2 * MED_W)
    # снежинки в свободных участках
    for x, y in free_spots(free, d.rng, 6, 18, spacing=60, inner=150):
        d.snowflake(x, y, d.rng.uniform(12, 17), a=0.82, w=1.2 * MED_W, rot=d.rng.uniform(0, 60), cold=d.rng.random() < 0.3)
    return d.image(disc_clip(MED, MED_R))


def medal_ice_comet(thumb):
    d = Ink(MED, MED, 37)
    common_ring(d)
    c = MED / 2
    free = free_mask(thumb)
    # диагональные линии траектории (хвост сверху слева, ядро снизу справа)
    ux, uy = math.cos(math.radians(48)), math.sin(math.radians(48))
    for k in range(-5, 6):
        off = k * 30
        x0, y0 = c - ux * 230 - uy * off, c - uy * 230 + ux * off
        pts = [(x0 + ux * t, y0 + uy * t) for t in np.linspace(0, 460, 50)]
        if k % 2:
            d.dashed(pts, dash=18, gap=10, w=1.1 * MED_W, a=0.62)
        else:
            d.line(pts, w=1.0 * MED_W, a=0.55, wob=0.5)
    # небольшой звёздный чертёж в свободном углу
    # звёздный чертёж: две группы в свободных углах (верх справа и низ слева)
    for corner in ((345, 150), (160, 370)):
        stars = [corner] + [(corner[0] + d.rng.uniform(-60, 60), corner[1] + d.rng.uniform(-50, 50)) for _ in range(7)]
        stars = [(x, y) for x, y in stars if math.hypot(x - c, y - c) < 150 and free[int(y), int(x)]]
        for (x0, y0), (x1, y1) in zip(stars, stars[1:]):
            d.line([(x0, y0), (x1, y1)], w=0.9 * MED_W, a=0.7, wob=0)
        for x, y in stars:
            d.star4(x, y, 7, a=0.9, w=1.0 * MED_W)
        if stars:
            d.circle(stars[0][0], stars[0][1], 22, w=0.9 * MED_W, a=0.6, dashed=True)
    # ледяная пыль
    for _ in range(150):
        x, y = d.rng.uniform(c - 170, c + 170), d.rng.uniform(c - 170, c + 170)
        if free[int(y), int(x)] and math.hypot(x - c, y - c) < 160:
            d.dot(x, y, d.rng.uniform(1.0, 2.2), a=d.rng.uniform(0.45, 0.8), cold=d.rng.random() < 0.3)
    return d.image(disc_clip(MED, MED_R))


def medal_absolute_zero(thumb):
    d = Ink(MED, MED, 41)
    common_ring(d)
    c = MED / 2
    # сеть трещин из точки за фигурой
    origin = (c + 6, c + 20)
    for k in range(11):
        ang = k * 32.7 + d.rng.uniform(-8, 8)
        d.crack(origin[0] + 22 * math.cos(math.radians(ang)), origin[1] + 22 * math.sin(math.radians(ang)),
                ang, d.rng.uniform(120, 160), depth=2, a=0.78, w=1.3 * MED_W)
    # кольцевые трещины-перемычки
    for r in (70, 125):
        for a0 in range(0, 360, 60):
            d.circle(origin[0], origin[1], r + d.rng.uniform(-6, 6), w=1.0 * MED_W, a=0.6,
                     a0=a0 + d.rng.uniform(0, 20), a1=a0 + d.rng.uniform(22, 40), wob=1.4)
    # морозные узоры у края
    for ang, (x, y) in ((-130, (380, 120)), (-50, (130, 120)), (200, (420, 330)), (-10, (95, 330))):
        d.fern(x, y, ang + 180, 70, depth=3, a=0.7, w=1.1 * MED_W, cold=False)
    return d.image(disc_clip(MED, MED_R))


def page_xy(x, y):
    """page px (origin centre, y up) -> texture px"""
    return ((x + PAGE_W / 2) * PX, (PAGE_H / 2 - y) * PX)


def right_page():
    W, H = int(PAGE_W * PX), int(PAGE_H * PX)
    d = Ink(W, H, 7)
    P = page_xy

    def circ(cx, cy, r, **kw):
        x, y = P(cx, cy)
        d.circle(x, y, r * PX, **kw)

    # Большой чертёж за анимацией: центр немного правее и выше середины области, чтобы был асимметричным
    cx, cy = 14.0, 300.0
    R = 418.0
    circ(cx, cy, R, w=2.6, a=0.82)
    circ(cx, cy, R - 12, w=1.3, a=0.7)
    # риски по ободу: каждые 5 градусов, длиннее каждые 30
    for k in range(72):
        t = math.radians(k * 5)
        r0 = R - 12
        r1 = r0 - (16 if k % 6 == 0 else 7)
        a0 = P(cx + r0 * math.cos(t), cy + r0 * math.sin(t))
        a1 = P(cx + r1 * math.cos(t), cy + r1 * math.sin(t))
        d.line([a0, a1], w=1.3 if k % 6 else 2.0, a=0.75, wob=0)
    # рунный пояс: короткие знаки из 2-3 штрихов
    rr = R - 40
    for k in range(36):
        t = math.radians(k * 10 + 5)
        gx, gy = cx + rr * math.cos(t), cy + rr * math.sin(t)
        tx, ty = -math.sin(t), math.cos(t)
        nx, ny = math.cos(t), math.sin(t)
        s = 9
        kind = k % 4
        a0 = P(gx - nx * s, gy - ny * s)
        a1 = P(gx + nx * s, gy + ny * s)
        d.line([a0, a1], w=1.3, a=0.72, wob=0)
        if kind == 0:
            d.line([P(gx + nx * s, gy + ny * s), P(gx + tx * s * 0.8, gy + ty * s * 0.8)], w=1.1, a=0.7, wob=0)
        elif kind == 1:
            d.line([P(gx - tx * s * 0.7, gy - ty * s * 0.7), P(gx + tx * s * 0.7, gy + ty * s * 0.7)], w=1.1, a=0.7, wob=0)
        elif kind == 2:
            d.circle(*P(gx + nx * s * 0.2, gy + ny * s * 0.2), 4 * PX, w=1.0, a=0.7, wob=0)
        else:
            d.line([P(gx - nx * s, gy - ny * s), P(gx + tx * s, gy + ty * s), P(gx + nx * s, gy + ny * s)], w=1.1, a=0.7, wob=0)
    circ(cx, cy, R - 62, w=1.4, a=0.72)
    # гексаграмма льда, вписанная в круг
    rh = R - 70
    for off in (90, 30):
        tri = [P(cx + rh * math.cos(math.radians(off + 120 * i)), cy + rh * math.sin(math.radians(off + 120 * i))) for i in range(4)]
        d.line(tri, w=1.6, a=0.72, wob=0.6)
    for i in range(6):
        t = math.radians(30 + 60 * i)
        vx, vy = cx + rh * math.cos(t), cy + rh * math.sin(t)
        circ(vx, vy, 17, w=1.3, a=0.75)
        circ(vx, vy, 9, w=1.0, a=0.6, cold=True)
    circ(cx, cy, rh * 0.5, w=1.3, a=0.65)
    circ(cx, cy, rh * 0.5 - 8, w=0.9, a=0.5, dashed=True)
    # 12 лучей снежинки в центре
    for k in range(12):
        t = math.radians(k * 30)
        r1 = rh * (0.5 if k % 2 == 0 else 0.38)
        d.line([P(cx + 26 * math.cos(t), cy + 26 * math.sin(t)), P(cx + r1 * math.cos(t), cy + r1 * math.sin(t))], w=1.1, a=0.6, wob=0)
    circ(cx, cy, 26, w=1.3, a=0.7)

    # Второй, малый чертёж — орбита у верхнего правого края, пересекает обод
    ox, oy = 330.0, 600.0
    circ(ox, oy, 104, w=1.5, a=0.75)
    circ(ox, oy, 70, w=1.0, a=0.6, dashed=True)
    for k in range(5):
        t = math.radians(200 + k * 33)
        px_, py_ = ox + 104 * math.cos(t), oy + 104 * math.sin(t)
        d.dot(*P(px_, py_), 4.0 * PX if k == 2 else 2.4 * PX, a=0.8)
    d.line([P(ox - 150, oy - 10), P(ox + 150, oy + 10)], w=0.9, a=0.5, wob=0.4)

    # Дуга траектории снизу слева, уходит за обод
    pts = [P(-520 + 520 * t, 40 + 260 * math.sin(math.pi * t * 0.9) - 160 * t) for t in np.linspace(0, 1, 60)]
    d.dashed(pts, dash=16, gap=9, w=1.2, a=0.6)

    # Связующие пунктиры: от знаков на полях к ободу чертежа (знаки — отдельные спрайты в сцене,
    # их места: SpellbookSceneBuilder.RightMarginSigns)
    for a_, b_ in (((-440, 452), (-398, 352)), ((-440, 12), (-400, 150)),
                   ((468, 512), (404, 470)), ((468, 52), (420, 170))):
        d.dashed([P(*a_), P(*b_)], dash=6, gap=6, w=1.0, a=0.6)

    # Небольшие этюды на полях: кристалл с размерной линией (у корешка), снежинка-построение (справа внизу)
    x, y = P(-440, 572)
    d.crystal(x, y, 34 * PX, rot=-12, a=0.82, w=1.5)
    d.line([P(-474, 527), P(-474, 617)], w=0.9, a=0.6, wob=0)
    for yy in (527, 617):
        d.line([P(-481, yy), P(-467, yy)], w=0.9, a=0.6, wob=0)
    x, y = P(470, -110)
    d.snowflake(x, y, 30 * PX, a=0.78, w=1.4)
    circ(470, -110, 38, w=0.9, a=0.55, dashed=True)

    img = d.image()
    # Штрих чертежа на листе уменьшается до ~0.6 экранного px на px листа: утолщаем линии на ~1 px
    # текстуры и чуть уплотняем, чтобы структура читалась, а не превращалась в дымку
    thick = np.asarray(img.split()[3].filter(ImageFilter.MaxFilter(3))).astype(np.float32)
    base = np.asarray(img).astype(np.float32)
    base[..., 3] = np.clip(np.maximum(base[..., 3] * 1.15, thick * 0.7), 0, 255)
    img = Image.fromarray(base.astype(np.uint8), "RGBA")
    # Ничего плотного ниже ленты названия: мягкий спад под y = -150
    al = np.asarray(img).astype(np.float32)
    ys = np.arange(H, dtype=np.float32)
    page_y = PAGE_H / 2 - ys / PX
    fade = np.clip((page_y + 175) / 30, 0, 1)
    # поля (|x| > 440) могут спускаться ниже — там нет текста
    xs = np.arange(W, dtype=np.float32) / PX - PAGE_W / 2
    margin = (np.abs(xs) > 440).astype(np.float32)
    keep = np.maximum(fade[:, None], margin[None, :])
    al[..., 3] *= keep
    return Image.fromarray(al.astype(np.uint8), "RGBA")


def main():
    for name, fn in (("Storm", medal_storm), ("FrostBreath", medal_frost_breath),
                     ("IceComet", medal_ice_comet), ("AbsoluteZero", medal_absolute_zero)):
        thumb = Image.open(UI / ("UI_Medal%s.png" % name)).convert("RGBA")
        fn(thumb).save(UI / ("UI_MedalUnder%s.png" % name), optimize=True)
    right_page().save(UI / "UI_RightPageInk.png", optimize=True)
    print("ok")


if __name__ == "__main__":
    main()
